using System.IO;using System.Windows;using System.Windows.Media.Imaging;using Microsoft.Win32;using SaarOSS.Rechnungsprogramm.Models;using SaarOSS.Rechnungsprogramm.Services;
namespace SaarOSS.Rechnungsprogramm.Views;
public partial class DocumentDesignWindow:Window
{
 readonly DocumentDesignService _service=new();DocumentDesignProfile _profile=new();public DocumentDesignWindow(){InitializeComponent();try{_profile=_service.Load();ShowLogoBox.IsChecked=_profile.ShowLogo;Line1Box.Text=_profile.HeaderLine1;Line2Box.Text=_profile.HeaderLine2;Line3Box.Text=_profile.HeaderLine3;Line4Box.Text=_profile.HeaderLine4;RefreshLogo();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Logo und Briefkopf",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void RefreshLogo(){var path=_service.LogoPath(_profile);var ok=path is not null&&File.Exists(path);NoLogoText.Visibility=ok?Visibility.Collapsed:Visibility.Visible;LogoImage.Source=null;if(ok){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(path!);image.EndInit();LogoImage.Source=image;}}
 void ChooseLogo(object s,RoutedEventArgs e){var d=new OpenFileDialog{Title="Unternehmenslogo auswählen",Filter="Bilddateien|*.png;*.jpg;*.jpeg;*.bmp",CheckFileExists=true};if(d.ShowDialog(this)!=true)return;try{_profile.LogoFileName=_service.ImportLogo(d.FileName);_profile.ShowLogo=true;ShowLogoBox.IsChecked=true;_service.Save(_profile);RefreshLogo();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Logo konnte nicht übernommen werden",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void RemoveLogo(object s,RoutedEventArgs e){if(MessageBox.Show(this,"Das intern gespeicherte Logo entfernen?","Logo entfernen",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{_service.RemoveLogo(_profile);RefreshLogo();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Logo entfernen",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void Save(object s,RoutedEventArgs e){_profile.ShowLogo=ShowLogoBox.IsChecked==true;_profile.HeaderLine1=Line1Box.Text.Trim();_profile.HeaderLine2=Line2Box.Text.Trim();_profile.HeaderLine3=Line3Box.Text.Trim();_profile.HeaderLine4=Line4Box.Text.Trim();try{_service.Save(_profile);MessageBox.Show(this,"Logo und Briefkopfeinstellungen wurden gespeichert.","Dokumentdesign",MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Speichern fehlgeschlagen",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void CloseWindow(object s,RoutedEventArgs e)=>Close();
}
